import assert from 'node:assert/strict';
import SuperJSON from './dist/index.js';
import {normalizeErrorStackOptions} from './dist/error-options.js';
import {processStackString,processStackFrames} from './dist/error-stack.js';
assert.equal(normalizeErrorStackOptions(null),undefined);
const stack='Error: hello\n    at x (/app/src/transformer.ts:1:1)\n    at y (node:internal/x:1:1)\n    at z (/tmp/file.js:2:3)';
let o=normalizeErrorStackOptions({mode:'string',redactPaths:'basename',stripInternalFrames:'superjson',maxStackLines:3});
assert.equal(processStackString(stack,o),'Error: hello\nat x (transformer.ts:1:1)\nat y (internal/x:1:1)');
o=normalizeErrorStackOptions({mode:'frames',stripInternalFrames:'node_and_superjson',redactPaths:'basename',maxStackLines:2});
assert.deepEqual(processStackFrames(stack,o),[{raw:'Error: hello'},{raw:'at z (file.js:2:3)'}]);
for (const mode of ['off','string','frames']) { const s=new SuperJSON({errorStack:{mode,includeCauses:'deep',maxCauseDepth:2}}); s.allowErrorProps('stack','stackFrames'); let e=new Error('a');e.stack=stack;let c=new Error('c');e.cause=c;c.cause=e; const r=s.serialize(e); assert.equal(r.meta.values[0],mode==='off'?'Error':`Error/${mode}`);assert.equal('stack' in r.json,mode==='string');assert.equal('stackFrames' in r.json,mode==='frames');assert.equal(r.json.cause.cause,undefined); }
const s=new SuperJSON({errorStack:{mode:'frames',includeCauses:'direct',sanitizeMessage:true}});s.allowErrorProps('stackFrames');let a=new AggregateError([new Date('2020-01-01')],'hello',{cause:new Error('a@b.com')});a.stack=stack;let r=s.parse(s.stringify(a));assert(r instanceof AggregateError);assert(r.errors[0] instanceof Date);assert.equal(r.cause.message,'[redacted]');
console.log('Detailed stack option checks passed');
